mapper.update:
UPDATE notification
   SET read_at = COALESCE(read_at, #{readAt})
 WHERE notification_id = #{notificationId}
   AND recipient_user_id = #{recipientUserId}

UPDATE notification
   SET read_at = #{readAt}
 WHERE recipient_user_id = #{recipientUserId}
   AND read_at IS NULL

mapper.delete:
DELETE FROM notification
 WHERE notification_id = #{notificationId}
   AND recipient_user_id = #{recipientUserId}
